"""Build an asset-free semantic accessibility viewer from private decoded inputs."""
import argparse,json,math
from pathlib import Path
from syndicate_scene import Terrain,canonical
from z_provider import WAYPOINTS

def build(data_dir,observation,out):
    terrain=Terrain((data_dir/'MAP01.DAT').read_bytes(),(data_dir/'COL01.DAT').read_bytes())
    scene=json.loads(observation.read_text());focus=next(e for e in scene['entities'] if e['id']==scene['selected'])
    layers=[];stats=[]
    for z in range(1,terrain.nz):
        c=terrain.components(z);layers.append({'z':z,'candidate':[[int(v) for v in row] for row in c['grid']],
        'support':[[terrain.column(x,y)[z-1] for x in range(terrain.nx)] for y in range(terrain.ny)]})
        stats.append({'z':z,'candidate_cells':sum(c['sizes']),'component_count':len(c['sizes']),
                      'largest_component':max(c['sizes'],default=0)})
    routes={}
    for category,n in scene['nearest'].items():
        if not n or category not in ('vehicle','civilian','guard','door'):continue
        path=terrain.path(tuple(map(int,focus['position'])),tuple(map(int,n['position'])))
        cells={tuple(p[:2]) for p in path or []}
        doors=[e['id'] for e in scene['entities'] if e['category']=='door' and tuple(map(int,e['position'][:2])) in cells]
        routes[category]={'destination':n['id'],'candidate_steps':len(path)-1 if path else None,
                          'path':path,'conditional_doors':doors,'qualification':'resource-model candidate only; dynamic gates, collision footprint and walking unverified'}
    model={'map_number':1,'dimensions':[terrain.nx,terrain.ny,terrain.nz],
           'source_hashes':{'map':terrain.map_sha256,'classes':terrain.classes_sha256},
           'layers':layers,'layer_stats':stats,'scene':scene,'candidate_routes':routes,
           'waypoints':[{'name':n,'position':list(p)} for n,p in WAYPOINTS.items()],
           'scope':'Semantic derivative. No original tile bytes, artwork or raw memory. Conditional surfaces are not certified routes.'}
    out.mkdir(parents=True,exist_ok=True)
    (out/'map-model.json').write_text(json.dumps(model,separators=(',',':')))
    template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Syndicate | Mission 1 spatial survey</title>
<style>body{margin:0;background:#101820;color:#e8eff4;font:16px system-ui,sans-serif}header{padding:22px 28px;border-bottom:1px solid #384854}h1{font-size:27px;margin:3px 0 10px}p{max-width:1120px;line-height:1.5}small,.muted{color:#b2c3ce}main{padding:20px 28px;display:grid;grid-template-columns:minmax(500px,1fr) 350px;gap:20px}.panel{background:#192630;border:1px solid #3b4b58;border-radius:8px;padding:16px}canvas{max-width:100%;width:100%;image-rendering:pixelated;background:#101820;cursor:crosshair}select,button{font:inherit;color:inherit;background:#283c4a;border:1px solid #577284;border-radius:4px;padding:7px}label{margin-right:14px}table{border-collapse:collapse;width:100%}td,th{padding:7px 5px;border-bottom:1px solid #344652;text-align:left}pre{white-space:pre-wrap;font:13px ui-monospace,monospace;line-height:1.5}.tag{display:inline-block;padding:6px 10px;background:#2b414f;border-radius:4px;margin:2px}#legend{line-height:2}.dot{display:inline-block;width:12px;height:12px;margin-right:6px}footer{padding:0 28px 26px}@media(max-width:980px){main{display:block}.panel{margin-bottom:16px}}</style>
<header><small>ORIGINAL-GAME OBSERVATION · RESEARCH / ASSISTED POLICY · 31 OCT 2026</small><h1>Mission 1: one spatial scene, not a stack of screenshots</h1><p>128 × 96 world tiles, 12 height layers. Live-state snapshot: four team agents, two civilians, four guards, one car and four doors. ★ identifies the explicit mission target. This file is an offline survey, not a live debugger connection.</p><span class="tag">44 registered spatial entities</span><span class="tag">26 occupied index cells</span><span class="tag">No walked routes certified</span></header>
<main><section class="panel"><div style="margin-bottom:12px"><label>Elevation <select id="level"></select></label><label>View <select id="view"><option value="district">Mission district</option><option value="all">Full map</option></select></label><label>Candidate route <select id="route"><option value="none">None</option><option value="vehicle">Nearest car</option><option value="civilian">Mission civilian</option><option value="guard">Nearest guard</option><option value="door">Nearest door</option></select></label></div><canvas id="map" width="1080" height="790"></canvas><p id="tile" class="muted">Point at a tile for its coordinates and conditional surface status. Select a higher layer to inspect rooftops without collapsing them into the ground floor.</p><div id="legend"><span class="dot" style="background:#46674f"></span>Conditional flat surface <span class="dot" style="background:#23303a"></span>Excluded / unresolved <span class="dot" style="background:#8b754c"></span>Candidate road support<br>A team · C civilian · G guard · P police · V car · D door · ★ mission target · ○ tested diagnostic waypoint<br>Dashed route: geometric candidate. Door state, slopes, actor footprint, vehicle entrances, traffic, hazards and line-of-sight remain unqualified.</div></section><aside><section class="panel"><h2 style="margin-top:0">Entity census</h2><table id="counts"></table><p>Counts describe registered records, not every possible spawn, living population or field of view. No police are registered at this boundary.</p></section><section class="panel"><h2 style="margin-top:0">Focus and nearest</h2><select id="focus"></select><pre id="nearest"></pre></section><section class="panel"><h2 style="margin-top:0">Route qualification</h2><div id="routeinfo">No candidate route selected.</div><p>Teleporting validates a prepared destination and subsequent state, not a traversable path. One exploratory point remained occupied despite being excluded by the terrain model; it is not an accepted waypoint.</p></section></aside></main><footer><p>Coordinates: x/y are original position fields ÷ 256; z is the height field ÷ 128. The flat-support/clearance classification is reference-informed and tested structurally against this edition's resources. Door open/closed state and vehicle gate/boarding relationships are unknown. Source identities and per-layer statistics are available in <a href="map-model.json" style="color:#a8cee8">map-model.json</a>.</p></footer>
<script>const model=__DATA__;
const canvas=document.getElementById('map'),ctx=canvas.getContext('2d');let transform;
const level=document.getElementById('level'),route=document.getElementById('route'),view=document.getElementById('view'),focus=document.getElementById('focus');
for(let z=1;z<model.dimensions[2];z++){let o=new Option('z='+z,z);level.add(o)}level.value=2;
for(const e of model.scene.team)focus.add(new Option(e.id+' '+JSON.stringify(e.position),e.id));focus.value=model.scene.selected;
const counts=document.getElementById('counts');counts.innerHTML='<tr><th>Type</th><th>Count</th></tr>'+Object.entries(model.scene.counts).filter(([k])=>!['weapon','tree'].includes(k)).map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('');
function nearest(){let s=model.scene.entities.find(e=>e.id===focus.value);let lines=[s.id+' @ '+s.position.join(', '),'health raw '+s.health_raw+'; life state not inferred',''];for(let cat of ['civilian','police','guard','agent','vehicle','door']){let a=model.scene.entities.filter(e=>e.category===cat&&e.id!==s.id).sort((a,b)=>Math.hypot(a.position[0]-s.position[0],a.position[1]-s.position[1])-Math.hypot(b.position[0]-s.position[0],b.position[1]-s.position[1]));lines.push(cat+': '+(a.length?`${a[0].id}\n  ${a[0].position.join(', ')}\n  XY ${Math.hypot(a[0].position[0]-s.position[0],a[0].position[1]-s.position[1]).toFixed(2)} tiles`:'none registered'))}document.getElementById('nearest').textContent=lines.join('\n')}
function draw(){let z=+level.value,L=model.layers.find(l=>l.z===z);const box=view.value==='all'?[0,0,128,96]:[40,20,100,60];let [x0,y0,x1,y1]=box;let pad=38,scale=Math.min((canvas.width-pad*2)/(x1-x0),(canvas.height-pad*2)/(y1-y0));transform={x0,y0,x1,y1,scale,pad};ctx.fillStyle='#101820';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){ctx.fillStyle=L.candidate[y][x]?([6,7,8,9,11,14,15].includes(L.support[y][x])?'#8b754c':L.support[y][x]===13?'#59617d':'#46674f'):'#23303a';ctx.fillRect(pad+(x-x0)*scale,pad+(y-y0)*scale,scale-.4,scale-.4)}
const point=p=>[pad+(p[0]-x0)*scale,pad+(p[1]-y0)*scale];let R=model.candidate_routes[route.value];if(R&&R.path){ctx.strokeStyle='#f5d16b';ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.beginPath();let first=true;for(let p of R.path){if(p[2]!==z)continue;let [x,y]=point([p[0]+.5,p[1]+.5]);first?ctx.moveTo(x,y):ctx.lineTo(x,y);first=false}ctx.stroke();ctx.setLineDash([])}
for(let w of model.waypoints){if(w.position[2]!==z)continue;let [x,y]=point(w.position);ctx.beginPath();ctx.strokeStyle='#bcdfe9';ctx.lineWidth=2;ctx.arc(x,y,Math.max(5,scale*.35),0,Math.PI*2);ctx.stroke()}
const symbols={agent:'A',civilian:'C',police:'P',guard:'G',vehicle:'V',door:'D'};ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';for(let e of model.scene.entities){let mark=e.mission_critical?'★':symbols[e.category];if(!mark||Math.floor(e.position[2])!==z)continue;let [x,y]=point(e.position);if(x<pad||y<pad||e.position[0]>=x1||e.position[1]>=y1)continue;ctx.fillStyle=e.mission_critical?'#f2b45f':e.category==='agent'?'#7adbe7':e.category==='guard'?'#f19a97':'#f0eff0';ctx.strokeStyle='#0a1118';ctx.lineWidth=4;ctx.strokeText(mark,x,y);ctx.fillText(mark,x,y)}
ctx.textAlign='center';ctx.fillStyle='#becdd7';ctx.font='12px system-ui';for(let x=Math.ceil(x0/5)*5;x<=x1;x+=5)ctx.fillText(x,pad+(x-x0)*scale,20);ctx.textAlign='right';for(let y=Math.ceil(y0/5)*5;y<=y1;y+=5)ctx.fillText(y,30,pad+(y-y0)*scale);ctx.textAlign='left';ctx.fillText('world x →',canvas.width-110,20);ctx.fillText('world y ↓',8,canvas.height-10);
let stat=model.layer_stats.find(s=>s.z===z);document.getElementById('routeinfo').textContent=R?`${R.destination}: ${R.candidate_steps??'no'} conditional same-level steps from initial agent 0. Door cells on path: ${R.conditional_doors.join(', ')||'none recorded'}. ${R.qualification}`:`Layer ${z}: ${stat.candidate_cells} conditional surface cells in ${stat.component_count} components. No inter-layer connectors are certified.`;nearest()}
canvas.onmousemove=ev=>{let r=canvas.getBoundingClientRect(),t=transform,x=Math.floor((ev.clientX-r.left)*canvas.width/r.width/t.scale-t.pad/t.scale+t.x0),y=Math.floor((ev.clientY-r.top)*canvas.height/r.height/t.scale-t.pad/t.scale+t.y0);if(x<0||y<0||x>=128||y>=96)return;let L=model.layers.find(l=>l.z===+level.value);let here=model.scene.entities.filter(e=>Math.floor(e.position[0])===x&&Math.floor(e.position[1])===y&&Math.floor(e.position[2])===+level.value);document.getElementById('tile').textContent=`(${x},${y},z=${level.value}) ${L.candidate[y][x]?'conditional surface':'excluded / unresolved'}; support class ${L.support[y][x]}; ${here.map(e=>e.id+(e.mission_critical?' [MISSION TARGET]':'')).join(', ')||'no registered entity in cell'}`};for(let e of [level,view,route,focus])e.onchange=draw;draw();
</script></html>'''
    (out/'mission-map.html').write_text(template.replace('__DATA__',json.dumps(model,separators=(',',':')).replace('</','<\\/')))
    summary={'dimensions':model['dimensions'],'source_hashes':model['source_hashes'],'layer_stats':stats,
             'routes':{k:{a:b for a,b in r.items() if a!='path'} for k,r in routes.items()},
             'qualification':model['scope']}
    (out/'map-summary.json').write_text(json.dumps(summary,indent=2))
    return summary
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('decoded_data',type=Path);ap.add_argument('observation',type=Path);ap.add_argument('output',type=Path);a=ap.parse_args()
    print(json.dumps(build(a.decoded_data,a.observation,a.output),indent=2))
